// Writes .env.local from the running local Supabase stack (used by CI and
// handy after `npm run db:start`).
import { execSync } from "node:child_process";
import { writeFileSync } from "node:fs";

const status = JSON.parse(execSync("npx supabase status -o json", { encoding: "utf8" }));
const lines = [
  "# Generated by scripts/ci-env.mjs from `supabase status` (local only).",
  `NEXT_PUBLIC_SUPABASE_URL=${status.API_URL}`,
  `NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY=${status.PUBLISHABLE_KEY ?? status.ANON_KEY}`,
  `SUPABASE_SECRET_KEY=${status.SECRET_KEY ?? status.SERVICE_ROLE_KEY}`,
  "NEXT_PUBLIC_ENABLE_DEV_LOGIN=true",
  "",
];
writeFileSync(new URL("../.env.local", import.meta.url), lines.join("\n"));
console.log("Wrote .env.local for", status.API_URL);
